CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT,first_name TEXT,coins INTEGER NOT NULL DEFAULT 500 CHECK(coins>=0),daily TEXT NOT NULL DEFAULT '',stats TEXT NOT NULL DEFAULT '{}',ach TEXT NOT NULL DEFAULT '{}',imported INTEGER NOT NULL DEFAULT 0,rday TEXT NOT NULL DEFAULT '',rtotal INTEGER NOT NULL DEFAULT 0,rlast TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT (datetime('now')),last_seen TEXT);
CREATE TABLE IF NOT EXISTS items(user_id INTEGER NOT NULL,item INTEGER NOT NULL,qty INTEGER NOT NULL CHECK(qty>=0),PRIMARY KEY(user_id,item));
CREATE TABLE IF NOT EXISTS catalog(id INTEGER PRIMARY KEY,name TEXT NOT NULL,descr TEXT NOT NULL,rarity INTEGER NOT NULL,price INTEGER NOT NULL CHECK(price>=0),color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(rid TEXT NOT NULL,user_id INTEGER NOT NULL,response TEXT NOT NULL,ts TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(rid,user_id));
CREATE TABLE IF NOT EXISTS admin_log(id INTEGER PRIMARY KEY AUTOINCREMENT,ts TEXT NOT NULL DEFAULT (datetime('now')),admin_id INTEGER NOT NULL,user_id INTEGER,type TEXT NOT NULL,amount INTEGER,result TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_users_seen ON users(last_seen);
